previewCss:
.darma-loader-darma-b13-database-stack { --accent: var(--loader-color, #0d9488); --accent-2: var(--loader-secondary-color, #5eead4); width: calc(var(--loader-size, 100px) * .82); height: calc(var(--loader-size, 100px) * .84); display: flex; flex-direction: column; justify-content: space-between; }
.darma-loader-darma-b13-database-stack span { position: relative; height: 30%; border-radius: 50% / 26%; background: linear-gradient(var(--accent), color-mix(in srgb, #000 26%, var(--accent))); animation: darma-loader-darma-b13-database-stack-query calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b13-database-stack span::after { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 36%; border-radius: 50%; background: color-mix(in srgb, #fff 28%, var(--accent-2)); }
.darma-loader-darma-b13-database-stack span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .2); }
.darma-loader-darma-b13-database-stack span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .4); }
@keyframes darma-loader-darma-b13-database-stack-query { 0%, 100% { box-shadow: 0 0 0 0 transparent; filter: brightness(1); } 45% { box-shadow: 0 0 calc(var(--loader-size, 100px) * .08) var(--accent-2); filter: brightness(1.22); } }

